PRAGMA foreign_keys = ON;

-- Handbook remediation: keep all seeded rows, convert future/slot-clone mail into historical, distinct crew-business facts.
UPDATE messages SET
  message_id = CASE message_id
    WHEN 'email_roster_0903' THEN 'email_history_roster_0824'
    WHEN 'email_roster_update_0911' THEN 'email_history_report_time_0826'
    WHEN 'email_swap_0924' THEN 'email_history_leave_process_0827'
    WHEN 'email_delay_1002' THEN 'email_history_delay_debrief_0829'
    ELSE message_id END,
  subject = CASE message_id
    WHEN 'email_roster_0903' THEN '8background noteArchivedbackground noteroster'
    WHEN 'email_roster_update_0911' THEN 'background note'
    WHEN 'email_swap_0924' THEN 'background note'
    WHEN 'email_delay_1002' THEN 'background notereviewbackground note'
    ELSE subject END,
  body_text = CASE message_id
    WHEN 'email_roster_0903' THEN '8background note；background note，background note9background note。'
    WHEN 'email_roster_update_0911' THEN '8background note，background notecompanybackground noteconfirmation；background noteemailbackground note。'
    WHEN 'email_swap_0924' THEN 'background note：background notecrew memberbackground notecompanybackground note，background note。'
    WHEN 'email_delay_1002' THEN '8background notereviewbackground note；background notesleepbackground note。'
    ELSE body_text END,
  date = CASE WHEN message_id IN ('email_roster_0903','email_roster_update_0911','email_swap_0924','email_delay_1002') THEN '2026-08-29T16:00:00+08:00' ELSE date END,
  created_at = CASE WHEN message_id IN ('email_roster_0903','email_roster_update_0911','email_swap_0924','email_delay_1002') THEN '2026-08-29T16:00:00+08:00' ELSE created_at END;

UPDATE messages
SET date = printf('2026-08-%02dT%02d:%02d:00+08:00', 1 + ((CAST(substr(message_id, -4) AS INTEGER) - 1) % 28), 8 + (CAST(substr(message_id, -4) AS INTEGER) % 11), CAST(substr(message_id, -4) AS INTEGER) % 60),
    created_at = printf('2026-08-%02dT%02d:%02d:00+08:00', 1 + ((CAST(substr(message_id, -4) AS INTEGER) - 1) % 28), 8 + (CAST(substr(message_id, -4) AS INTEGER) % 11), CAST(substr(message_id, -4) AS INTEGER) % 60),
    subject = CASE (CAST(substr(message_id, -4) AS INTEGER) % 15)
      WHEN 0 THEN 'background note' WHEN 1 THEN 'background note' WHEN 2 THEN 'background noteupdate'
      WHEN 3 THEN 'background note' WHEN 4 THEN 'background note' WHEN 5 THEN 'background note'
      WHEN 6 THEN 'background note' WHEN 7 THEN 'background note' WHEN 8 THEN 'background note'
      WHEN 9 THEN 'background note' WHEN 10 THEN 'background notemaintain' WHEN 11 THEN 'background note'
      WHEN 12 THEN 'background note' WHEN 13 THEN 'background note' ELSE 'background note' END,
    body_text =
      CASE (CAST(substr(message_id, -4) AS INTEGER) % 15)
        WHEN 0 THEN 'background note。' WHEN 1 THEN 'background noteairportbackground note。'
        WHEN 2 THEN 'background noteupdatebackground note。' WHEN 3 THEN 'background note。'
        WHEN 4 THEN 'background note。' WHEN 5 THEN 'background noteconfirmationbackground note。'
        WHEN 6 THEN 'background note。' WHEN 7 THEN 'background note。'
        WHEN 8 THEN 'background note。' WHEN 9 THEN 'background notemaintainbackground note。'
        WHEN 10 THEN 'rosterbackground notemaintainbackground note。' WHEN 11 THEN 'background note。'
        WHEN 12 THEN 'background note。' WHEN 13 THEN 'background note。'
        ELSE 'background note、background note。' END
      || ' '
      || CASE CAST((CAST(substr(message_id, -4) AS INTEGER) - 1) / 15 AS INTEGER)
        WHEN 0 THEN 'statusbackground note，background note。' WHEN 1 THEN 'background notecrew memberbackground noteconfirmationbackground note。'
        WHEN 2 THEN 'background notecalendarbackground note，background noterecordbackground note，background notecompanybackground note。' WHEN 3 THEN 'background note。'
        WHEN 4 THEN 'background note。' WHEN 5 THEN 'background note，background note。'
        WHEN 6 THEN 'background note，background note。' WHEN 7 THEN 'background note，background note。'
        WHEN 8 THEN 'background note，background noterecordbackground note。' WHEN 9 THEN 'background noteconfirmationLocationbackground note。'
        WHEN 10 THEN 'background notePre-flight preparationbackground note。' WHEN 11 THEN 'background notecrew memberbackground note。'
        WHEN 12 THEN 'background note，background note。' WHEN 13 THEN 'background note，background note。'
        ELSE 'background note，background note。' END
      || ' emailbackground note=' || date || '；background note=' || from_addr || '。'
WHERE message_id LIKE 'email_bg_%';

-- Historical distractor messages do not carry future scenario dates or facts
-- in their prose; their actual message date remains the authoritative time.
UPDATE messages
SET body_text = 'Historical mailbox record; review only if relevant to the current request.'
WHERE message_id LIKE 'email_bg_%';
